{
  "name": "pi-commit-split",
  "version": "0.2.0",
  "description": "Adaptive topic-based commit workflow for Pi and OpenCode",
  "scripts": {
    "test:core": "bun test tests/commit-core.test.ts"
  },
  "keywords": [
    "pi-package",
    "pi",
    "opencode",
    "git",
    "commit"
  ],
  "license": "MIT",
  "files": [
    "extensions",
    ".opencode",
    "README.md",
    "CHANGELOG.md",
    "LICENSE",
    "package.json"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/ismailokta/pi-commit-split"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "@earendil-works/pi-tui": "*",
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "pi": {
    "extensions": [
      "./extensions/commit-workflow.ts"
    ]
  },
  "exports": {
    "./tui": "./extensions/opencode-plugin.tsx"
  }
}
